6	const TYPE_THRESHOLD = 3;
7	
8	const isSphinx = (card: Card): boolean => card.monster === "sphinx";
9	
10	const typeOf = (card: Card): string => `${card.monster}:${card.rank}`;
11	
12	const countDistinctTypes = (army: Card[]): number =>
13	  new Set(army.map(typeOf)).size;
14	
15	const pointsPerSphinxFor = (typeCount: number): number =>
16	  typeCount > TYPE_THRESHOLD ? 2 * (typeCount - TYPE_THRESHOLD) : 1;
